{
  "findings": [
    {
      "check_id": "CKV_AWS_261",
      "title": "Ensure HTTP HTTPS Target group defines Healthcheck",
      "resource": "aws_alb_target_group.pass",
      "severity": "MEDIUM",
      "explanation": "The target group is using a non-HTTP/HTTPS protocol (TCP) but still should have a health check defined for its targets."
    }
  ],
  "patched_code": "resource "aws_alb_target_group" "pass" {
  name     = "tf-example-lb-nlb-tg"
  port     = 25
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  target_health_state {
    enable_unhealthy_connection_termination = false
  }

  health_check {
    healthy_threshold   = 3
    unhealthy_threshold = 3
    interval            = 30
    protocol            = "TCP"
    port                = "traffic-port"
  }
}",
  "fix_summary": "Added a health check block to the aws_alb_target_group resource to ensure targets are properly monitored."
}
